/**
 * sumAmounts — total a feed of line-item amounts.
 *
 * Each row carries `amount` as a string (the export serialises money as text).
 * Handles both en-US (1,234.56) and de-DE (1.234,56) locale conventions
 * so that intermixed rows are summed correctly.
 */

function roundTo2(n) {
  return Math.floor(n * 100 + (n >= 0 ? 0.5 : -0.5)) / 100;
}

function parseAmount(str) {
  if (typeof str !== 'string') return 0;

  var s = str.trim();
  if (s === '') return 0;

  // Strip leading currency symbols ($, €, £, ¥ …) and any prefix junk.
  s = s.replace(/^[^\d.,+\-]+/, '');
  if (s === '' || s === '.' || s === ',' || s === '+' || s === '-') return 0;

  var lastComma  = s.lastIndexOf(',');
  var lastPeriod = s.lastIndexOf('.');

  var numStr;

  if (lastComma === -1 && lastPeriod === -1) {
    // No separators at all — plain number.
    numStr = s;
  } else if (lastComma === -1) {
    // Only periods.  Heuristic: > 2 digits after the last period ⇒ thousands sep.
    if (s.substring(lastPeriod + 1).length > 2) {
      numStr = s.replace(/\./g, '');   // 1.234  →  1234
    } else {
      numStr = s;                      // 12.50  →  12.50
    }
  } else if (lastPeriod === -1) {
    // Only commas — European decimal (e.g. "1234,56").
    numStr = s.replace(',', '.');
  } else if (lastPeriod > lastComma) {
    // Period after comma — US format (1,234.56).
    numStr = s.replace(/,/g, '');
  } else {
    // Comma after period — European format (1.234,56).
    numStr = s.replace(/\./g, '').replace(',', '.');
  }

  var num = Number(numStr);
  return isNaN(num) ? 0 : num;
}

/**
 * @param {Array<{amount: string, currency?: string}>} rows
 * @returns {number} grand total, rounded to 2 decimal places (half-up)
 */
function sumAmounts(rows) {
  var total = 0;
  for (var i = 0; i < rows.length; i++) {
    total += parseAmount(rows[i].amount);
  }
  return roundTo2(total);
}

module.exports = { sumAmounts };

